    question_en: "If x + 1/x = 4, then find the value of (x⁴ + 1/x²)/(x² - 3x + 1).",
    question_hi: "यदि x + 1/x = 4 है, तो (x⁴ + 1/x²)/(x² - 3x + 1) का मान ज्ञात कीजिए।",
    option_a_en: "52",
