    explanation_en: "The radius of the smaller circle (5 cm) is perpendicular to the tangent chord at the point of contact, bisecting it. Half chord = √(13² - 5²) = √(169 - 25) = √144 = 12 cm. Full chord length = 2 × 12 = 24 cm.",
