    correct_option: 0,
    explanation_en: "Divide numerator and denominator by x: (x³ + 1/x³)/(x - 3 + 1/x). Since x + 1/x = 4, x³ + 1/x³ = 4³ - 3(4) = 64 - 12 = 52. Denominator = (x + 1/x) - 3 = 4 - 3 = 1. Value = 52 / 1 = 52.",
    explanation_hi: "अंश और हर को x से विभाजित करने पर: (x³ + 1/x³)/(x - 3 + 1/x)। x + 1/x = 4 है, अतः x³ + 1/x³ = 4³ - 3(4) = 52। हर = (x + 1/x) - 3 = 4 - 3 = 1। उत्तर = 52 / 1 = 52।",
